CREATE OR REPLACE FUNCTION private.crm_classification_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p crm_catalogs; t crm_catalogs; BEGIN PERFORM pg_advisory_xact_lock(hashtext('crm_catalogs')); IF TG_TABLE_NAME='crm_catalogs' THEN IF NEW.kind='group' AND NEW.parent_id IS NOT NULL THEN RAISE EXCEPTION 'Nhóm khách phải là danh mục gốc.'; END IF; IF NEW.kind IN ('segment','block') THEN SELECT * INTO p FROM crm_catalogs WHERE id=NEW.parent_id; IF p.id IS NULL OR p.kind<>ALL(ARRAY['group','block']) THEN RAISE EXCEPTION 'Tệp khách cần thuộc Nhóm hoặc Khối khách.'; END IF; END IF; IF TG_OP='UPDATE' AND NEW.parent_id IS DISTINCT FROM OLD.parent_id AND EXISTS(SELECT 1 FROM crm_customers WHERE segment_id=OLD.id OR OLD.id=ANY(related_ids)) THEN RAISE EXCEPTION 'Tệp đã có khách sử dụng; không thể đổi nhóm cha.'; END IF; IF EXISTS(SELECT 1 FROM crm_catalogs c WHERE c.id<>NEW.id AND c.kind=NEW.kind AND c.parent_id IS NOT DISTINCT FROM NEW.parent_id AND lower(trim(c.name))=lower(trim(NEW.name))) THEN RAISE EXCEPTION 'Tên danh mục đã tồn tại trong nhóm này.'; END IF; IF NEW.config ? 'group_ids' THEN IF jsonb_typeof(NEW.config->'group_ids')<>'array' THEN RAISE EXCEPTION 'Phạm vi nhóm không hợp lệ.'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.config->'group_ids') x WHERE NOT EXISTS(SELECT 1 FROM crm_catalogs c WHERE c.id=x::uuid AND c.kind='group')) THEN RAISE EXCEPTION 'Phạm vi nhóm không hợp lệ.'; END IF; END IF; ELSE IF NEW.segment_id IS NOT NULL AND NEW.group_id IS NULL THEN RAISE EXCEPTION 'Vui lòng chọn Nhóm trước Tệp khách.'; END IF; FOREACH t IN ARRAY ARRAY[]::crm_catalogs[] LOOP END LOOP; FOR t IN SELECT * FROM crm_catalogs WHERE id=ANY(NEW.related_ids) LOOP IF t.config ? 'group_ids' AND jsonb_array_length(t.config->'group_ids')>0 AND NOT coalesce(t.config->'group_ids' ? NEW.group_id::text,false) AND (TG_OP='INSERT' OR NOT t.id=ANY(OLD.related_ids)) THEN RAISE EXCEPTION 'Đặc điểm không thuộc phạm vi nhóm đã chọn.'; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_classification_catalog BEFORE INSERT OR UPDATE ON public.crm_catalogs FOR EACH ROW EXECUTE FUNCTION private.crm_classification_guard();
CREATE TRIGGER crm_classification_customer BEFORE INSERT OR UPDATE ON public.crm_customers FOR EACH ROW EXECUTE FUNCTION private.crm_classification_guard();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.crm_catalog_save(jsonb)'::regprocedure) INTO d; d:=replace(d,'''cooperation'',''occasion''','''cooperation'',''occasion'',''output'''); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.crm_catalog_counts() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT crm_can(auth.uid(),'biz.crm_settings') THEN RAISE EXCEPTION 'Bạn không có quyền cài đặt CRM.'; END IF; RETURN (SELECT coalesce(jsonb_object_agg(id,n),'{}') FROM (SELECT cat.id,count(c.id) n FROM crm_catalogs cat LEFT JOIN crm_customers c ON (c.group_id=cat.id OR c.segment_id=cat.id OR cat.id=ANY(c.related_ids)) AND crm_owner_visible(c.owner_id) GROUP BY cat.id) q); END $$;
CREATE OR REPLACE FUNCTION public.crm_report_filtered(_start date,_end date,_mine boolean DEFAULT true,_owner uuid DEFAULT NULL,_group uuid DEFAULT NULL,_province text DEFAULT NULL,_department uuid DEFAULT NULL,_system uuid DEFAULT NULL,_team uuid DEFAULT NULL,_segment uuid DEFAULT NULL,_priority uuid DEFAULT NULL,_relationship uuid DEFAULT NULL,_export boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; cs jsonb; ss jsonb; ii jsonb; totals jsonb; lo timestamptz:=_start::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'; hi timestamptz; BEGIN IF _export AND NOT crm_can(auth.uid(),'biz.crm_export') THEN RAISE EXCEPTION 'Bạn không có quyền xuất CRM.'; END IF; r:=crm_report(_start,_end,_mine,_owner,_group,_province,_department,_system,_team); hi:=(r->>'as_of')::timestamptz;
SELECT coalesce(jsonb_agg(x),'[]') INTO cs FROM jsonb_array_elements(r->'customers') x WHERE (_segment IS NULL OR x->>'segment_id'=_segment::text) AND (_priority IS NULL OR x->>'priority_id'=_priority::text) AND (_relationship IS NULL OR x->>'relationship_id'=_relationship::text);
SELECT coalesce(jsonb_agg(x),'[]') INTO ss FROM jsonb_array_elements(r->'schedules') x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(cs) c WHERE c->>'id'=x->>'customer_id');
SELECT coalesce(jsonb_agg(x),'[]') INTO ii FROM jsonb_array_elements(r->'interactions') x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(cs) c WHERE c->>'id'=x->>'customer_id');
WITH customers AS (SELECT x FROM jsonb_array_elements(cs) x), schedules AS (SELECT x,(x->>'original_due_at')::timestamptz due FROM jsonb_array_elements(ss) x), interactions AS (SELECT x FROM jsonb_array_elements(ii) x) SELECT jsonb_build_object('customers',(SELECT count(DISTINCT x->>'id') FROM customers),'new_customers',(SELECT count(*) FROM customers WHERE (x->>'created_at')::timestamptz>=lo),'priority_customers',(SELECT count(*) FROM customers JOIN crm_catalogs c ON c.id=(x->>'priority_id')::uuid WHERE coalesce((c.config->>'key_customer')::boolean,false)),'cooperating_customers',(SELECT count(*) FROM customers JOIN crm_catalogs c ON c.id=(x->>'relationship_id')::uuid WHERE coalesce((c.config->>'cooperating')::boolean,false)),'unclassified_customers',(SELECT count(*) FROM customers WHERE x->>'segment_id' IS NULL),'scheduled_customers',(SELECT count(*) FROM customers c WHERE EXISTS(SELECT 1 FROM schedules s WHERE s.x->>'customer_id'=c.x->>'id' AND s.x->>'status'='pending')),'due',(SELECT count(*) FROM schedules WHERE due>=lo AND due<hi),'processed',(SELECT count(*) FROM schedules WHERE due>=lo AND due<hi AND x->>'processed_at' IS NOT NULL),'on_time',(SELECT count(*) FROM schedules WHERE due>=lo AND due<hi AND (x->>'completed_at')::timestamptz<=due),'overdue',(SELECT count(*) FROM schedules WHERE due<hi AND x->>'status'='pending'),'overdue_customers',(SELECT count(DISTINCT x->>'customer_id') FROM schedules WHERE due<hi AND x->>'status'='pending'),'priority_overdue',(SELECT count(*) FROM customers c JOIN crm_catalogs cat ON cat.id=(c.x->>'priority_id')::uuid WHERE coalesce((cat.config->>'key_customer')::boolean,false) AND EXISTS(SELECT 1 FROM schedules s WHERE s.x->>'customer_id'=c.x->>'id' AND due<hi AND s.x->>'status'='pending')),'attempts',(SELECT count(*) FROM interactions),'connected',(SELECT count(*) FROM interactions WHERE (x->>'connected')::boolean)) INTO totals;
RETURN r || jsonb_build_object('customers',cs,'schedules',ss,'interactions',ii,'totals',totals); END $$;
REVOKE ALL ON FUNCTION public.crm_catalog_counts() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_catalog_counts() TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.crm_report_filtered(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid,uuid,uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_report_filtered(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid,uuid,uuid,uuid,boolean) TO authenticated,service_role;